def require_numeric_qsort_helper_slice(family: Mapping[str, Any]) -> None:
    """Keep musl's private qsort helper selected without promoting sorting."""
    slices = require_verified_slices(
        family.get("verified_slice"),
        "family[libc.c-abi-compat].verified_slice",
        family.get("status", ""),
        list(family.get("capabilities", [])),
    )
    matching = [entry for entry in slices if entry.get("id") == "numeric.qsort-helper"]
    require(
        len(matching) == 1,
        "libc.c-abi-compat needs one numeric.qsort-helper slice",
    )
    require(
        family.get("status") == "planned",
        "qsort helper selection must not promote libc.c-abi-compat",
    )
    selected = matching[0]
    require(
        selected["capabilities"] == ["numeric.qsort-helper"],
        "qsort helper slice must select exactly numeric.qsort-helper",
    )
    description = selected["description"]
    assert isinstance(description, str)
    for phrase in (
        "still-planned `libc.c-abi-compat`",
        "uninstalled `__qsort_r` helper",
        "weak same-address `qsort_r` alias",
        "O(1) cycling buffer",
        "numeric.scalar-legacy-callback",
        "separate `search.hash-table` selection remains private",
        "promotion/public_support=false",
        "public x86 support",
    ):
        require(
            phrase in description,
            f"numeric.qsort-helper description omits {phrase}",
        )

    owners = set(
        nonempty_strings(
            selected["source_owners"], "numeric.qsort-helper.source_owners"
        )
    )
    for owner in (
        "libc/src/c_abi/x86_64/qsort.rs",
        "libc/src/c_abi/x86_64/callback_algorithms.rs",
        "include/stdlib.h",
        "compat/x86_64/callback_algorithms_header_abi_probe.c",
        "compat/x86_64/callback_algorithms_header_abi_probe.cpp",
        "compat/x86_64/libc_callback_algorithms_probe.c",
        "compat/x86_64/libc_callback_algorithms_start.S",
        "compat/x86_64/run_callback_algorithms_header_abi.sh",
        "compat/x86_64/run_libc_callback_algorithms.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/aarch64_parity_inventory.json",
        "scripts/dev-x86_64.sh",
    ):
        require(
            owner in owners,
            f"numeric.qsort-helper source owners omit {owner}",
        )

    prerequisites = nonempty_strings(
        selected["x86_abi_prerequisites"], "numeric.qsort-helper.x86_abi_prerequisites"
    )
    for phrase in (
        "SysV AMD64 LP64",
        "rdi/rsi/rdx/rcx/r8",
        "weak `qsort_r`",
        "14 * sizeof(size_t) + 1",
        "C longjmp and C++ exceptions",
    ):
        require(
            any(phrase in item for item in prerequisites),
            f"numeric.qsort-helper ABI prerequisites omit {phrase}",
        )
    headers = nonempty_strings(
        selected["x86_header_prerequisites"], "numeric.qsort-helper.x86_header_prerequisites"
    )
    require(
        any(
            "__qsort_r" in item and "uninstalled" in item and "C++17" in item
            for item in headers
        ),
        "numeric.qsort-helper must preserve private-helper header visibility",
    )

    exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    for symbol in (*QSORT_HELPER_SYMBOLS, "qsort_r"):
        require(symbol in exports, f"static C ABI export contract omits {symbol}")
    for symbol in ("malloc", "calloc", "realloc", "free"):
        require(
            symbol not in exports,
            f"numeric.qsort-helper selects allocator export {symbol}",
        )

    callback_source = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "callback_algorithms.rs"
    ).read_text(encoding="utf-8")
    qsort_source = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "qsort.rs"
    ).read_text(encoding="utf-8")
    for snippet in (
        "src/stdlib/qsort.c::__qsort_r",
        ".weak qsort_r",
        ".set qsort_r, __qsort_r",
        "pub unsafe extern \"C\" fn __qsort_r",
        "qsort_with_context",
    ):
        require(
            snippet in callback_source,
            f"numeric.qsort-helper context ABI source omits {snippet}",
        )
    for snippet in (
        "src/stdlib/qsort.c::__qsort_r",
        "qsort_with_context",
        "14 * core::mem::size_of::<usize>() + 1",
        "12 * core::mem::size_of::<usize>()",
    ):
        require(
            snippet in qsort_source,
            f"numeric.qsort-helper smoothsort source omits {snippet}",
        )

    evidence = selected["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-callback-algorithms"},
        "numeric.qsort-helper must use the closed libc-callback-algorithms command",
    )
    scope = evidence[0]["scope"]
    assert isinstance(scope, str)
    for phrase in (
        "pinned-musl",
        "hidden __qsort_r helper",
        "weak same-address alias",
        "caller strong override",
        "public x86 support",
    ):
        require(
            phrase in scope,
            f"numeric.qsort-helper evidence omits {phrase}",
        )
    runner = (
        ROOT / "compat" / "x86_64" / "run_libc_callback_algorithms.sh"
    ).read_text(encoding="utf-8")
    fixture = (
        ROOT / "compat" / "x86_64" / "libc_callback_algorithms_probe.c"
    ).read_text(encoding="utf-8")
    for snippet in (
        "assert_musl_weak_alias",
        "__qsort_r",
        "qsort_r",
        "CRABC_CALLBACK_ALGORITHMS_OVERRIDE_QSORT_R",
        "-nostdlib -static",
    ):
        require(
            snippet in runner,
            f"numeric.qsort-helper runner omits {snippet}",
        )
    for snippet in (
        "__qsort_r",
        "check_context_sort",
        "qsort_r_override_called",
        "CRABC_CALLBACK_ALGORITHMS_OVERRIDE_QSORT_R",
    ):
        require(
            snippet in fixture,
            f"numeric.qsort-helper fixture omits {snippet}",
        )
    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    require(
        "run_libc_callback_algorithms.sh" in dispatcher,
        "numeric.qsort-helper dispatcher binding is missing",
    )


def require_descriptor_lifecycle_artifact(family: Mapping[str, Any]) -> None:
    """Keep the composed descriptor proof private and tied to its boundaries."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.posix-runtime].verified_artifact",
        family.get("status", ""),
    )
    matching = [
        entry
        for entry in artifacts
        if entry.get("id") == "static-c-descriptor-lifecycle"
    ]
    require(
        len(matching) == 1,
        "libc.posix-runtime must contain exactly one static-c-descriptor-lifecycle artifact",
    )
    require(
        family.get("status") == "planned",
        "static-c-descriptor-lifecycle must not promote libc.posix-runtime",
    )
    artifact = matching[0]
    description = artifact["description"]
    assert isinstance(description, str)
    for phrase in (
        "descriptor-lifecycle composition",
        "`open`",
        "`openat`",
        "`creat`",
        "`fstat`/`fstatat`",
        "O_CLOEXEC",
        "O_LARGEFILE",
        "shared open-file-description status",
        "Fixture-local raw Linux calls",
        "does not establish a general C runtime",
        "public x86 support",
    ):
        require(
            phrase in description,
            f"static-c-descriptor-lifecycle description omits {phrase}",
        )

    owners = set(
        nonempty_strings(
            artifact["source_owners"], "static-c-descriptor-lifecycle.source_owners"
        )
    )
    for owner in (
        "compat/upstreams.toml",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/errno.rs",
        "libc/src/c_abi/x86_64/syscall.rs",
        "libc/src/c_abi/x86_64/stat_compat.rs",
        "libc/src/c_abi/x86_64/descriptor_entry.rs",
        "libc/src/c_abi/x86_64/descriptor_control.rs",
        "libc/src/c_abi/x86_64/descriptor_io.rs",
        "include/fcntl.h",
        "include/stddef.h",
        "include/sys/stat.h",
        "include/unistd.h",
        "compat/x86_64/fcntl_header_abi_probe.c",
        "compat/x86_64/run_fcntl_header_abi.sh",
        "compat/x86_64/stat_header_abi_probe.c",
        "compat/x86_64/run_stat_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_descriptor_lifecycle_probe.c",
        "compat/x86_64/libc_descriptor_lifecycle_start.S",
        "compat/x86_64/run_libc_descriptor_lifecycle.sh",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "scripts/dev-x86_64.sh",
    ):
        require(
            owner in owners,
            f"static-c-descriptor-lifecycle source owners omit {owner}",
        )

    prerequisites = nonempty_strings(
        artifact["x86_abi_prerequisites"],
        "static-c-descriptor-lifecycle.x86_abi_prerequisites",
    )
    require(
        any(
            "open=2" in item
            and "openat=257" in item
            and "fcntl=72" in item
            and "rdi/rsi/rdx" in item
            and "r10" in item
            and "F_GETFD/F_GETFL" in item
            for item in prerequisites
        ),
        "static-c-descriptor-lifecycle must record its entry and variadic fcntl ABI",
    )
    require(
        any(
            "fstat=5" in item
            and "fstatat" in item
            and "newfstatat=262" in item
            and "144-byte x86 LP64 record" in item
            and "r10" in item
            for item in prerequisites
        ),
        "static-c-descriptor-lifecycle must record its selected stat ABI",
    )
    require(
        any(
            "FD_CLOEXEC" in item
            and "shared open file description" in item
            and "O_APPEND" in item
            and "initial-TLS errno" in item
            for item in prerequisites
        ),
        "static-c-descriptor-lifecycle must record descriptor-state and errno ownership",
    )
    require(
        any(
            "PT_TLS errno datum" in item
            and "Variant-II thread-pointer self word" in item
            for item in prerequisites
        ),
        "static-c-descriptor-lifecycle must record its fixture-only TLS boundary",
    )

    headers = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-descriptor-lifecycle.x86_header_prerequisites",
    )
    require(
        any(
            "fcntl C/C++ gate" in item
            and "stat C/C++ gate" in item
            and "not header closure" in item
            for item in headers
        ),
        "static-c-descriptor-lifecycle must retain its existing header-gate boundary",
    )

    static_exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    for symbol in (
        "open",
        "openat",
        "creat",
        "fcntl",
        "read",
        "write",
        "pread",
        "pwrite",
        "lseek",
        "fstat",
        "fstatat",
        "dup",
        "dup2",
        "dup3",
        "ftruncate",
        "fsync",
        "fdatasync",
        "close",
    ):
        require(
            symbol in static_exports,
            f"static-c-descriptor-lifecycle must retain selected export {symbol}",
        )

    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-descriptor-lifecycle"},
        "static-c-descriptor-lifecycle must use the closed libc-descriptor-lifecycle command",
    )
    scope = evidence[0].get("scope")
    require(
        isinstance(scope, str)
        and all(
            phrase in scope
            for phrase in (
                "Pinned-musl C reference",
                "`-nostdlib -static` candidate",
                "PT_TLS capacity",
                "PID-isolated descriptor-relative lifecycle",
                "O_CLOEXEC/O_LARGEFILE",
                "fstat/fstatat",
                "dup/dup2/dup3",
                "public x86 support",
            )
        ),
        "static-c-descriptor-lifecycle evidence must retain its bounded composition scope",
    )


