def require_named_locale_multibyte_artifact(family: Mapping[str, Any]) -> None:
    """Keep the named-locale/text archive slice below locale-family completion.

    The static artifact owns a deliberately closed subset of musl's ordinary
    locale and multibyte entries. It is not a locale database, object API, or
    wide-stdio claim, so the validator pins its named states, exact mixed-form
    parser, ABI layout, static link boundary, and non-promotion wording.
    """
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.text-math-locale-stdio].verified_artifact",
        family.get("status", ""),
    )
    matching = [
        entry
        for entry in artifacts
        if entry.get("id") == "static-c-named-locale-multibyte"
    ]
    require(
        len(matching) == 1,
        "libc.text-math-locale-stdio must contain exactly one static-c-named-locale-multibyte artifact",
    )
    artifact = matching[0]
    description = artifact["description"]
    assert isinstance(description, str)
    for symbol in NAMED_LOCALE_MULTIBYTE_SYMBOLS:
        require(
            symbol in description,
            f"static-c-named-locale-multibyte description omits {symbol}",
        )
    for phrase in (
        "named C locale/multibyte core",
        "C.UTF-8",
        "POSIX",
        "six-component mixed `LC_ALL` serialization",
        "LC_CTYPE",
        "C code units",
        "UTF-8",
        "positive-capacity UTF-8 resume",
        "lconv",
        "EILSEQ",
        "locale objects",
        "per-thread locale overrides",
        "wide streams",
        "family completion",
        "promotion",
        "public x86 support",
    ):
        require(
            phrase in description,
            f"static-c-named-locale-multibyte description omits {phrase}",
        )

    owners = nonempty_strings(
        artifact["source_owners"], "static-c-named-locale-multibyte.source_owners"
    )
    for owner in (
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/locale_multibyte.rs",
        "include/bits/alltypes.h",
        "include/limits.h",
        "include/locale.h",
        "include/stdlib.h",
        "include/wchar.h",
        "compat/x86_64/locale_multibyte_header_abi_probe.c",
        "compat/x86_64/locale_multibyte_header_abi_probe.cpp",
        "compat/x86_64/run_locale_multibyte_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_locale_multibyte_probe.c",
        "compat/x86_64/libc_locale_multibyte_start.S",
        "compat/x86_64/run_libc_locale_multibyte.sh",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/validate_parity_ledger.py",
        "scripts/dev-x86_64.sh",
    ):
        require(
            owner in owners,
            f"static-c-named-locale-multibyte omits {owner}",
        )

    abi_prerequisites = nonempty_strings(
        artifact["x86_abi_prerequisites"],
        "static-c-named-locale-multibyte.x86_abi_prerequisites",
    )
    require(
        any(
            "signed 32-bit wchar_t" in item
            and "unsigned 32-bit wint_t" in item
            and "8-byte/align-4 mbstate_t" in item
            and "96-byte/align-8" in item
            for item in abi_prerequisites
        ),
        "static-c-named-locale-multibyte must record the x86 public layouts",
    )
    require(
        any(
            "CODEUNIT" in item
            and "BITTAB/OOB" in item
            and "mbrtowc/mbrlen" in item
            and "locale_map.c" in item
            for item in abi_prerequisites
        ),
        "static-c-named-locale-multibyte must record its musl state machine boundary",
    )
    require(
        any("initial-exec errno" in item for item in abi_prerequisites),
        "static-c-named-locale-multibyte must record its selected errno seam",
    )

    header_prerequisites = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-named-locale-multibyte.x86_header_prerequisites",
    )
    require(
        any(
            "C11/C++17" in item and "unmangled C++" in item and "locale_t" in item
            for item in header_prerequisites
        ),
        "static-c-named-locale-multibyte must record the strict C/C++ header boundary",
    )
    require(
        any(
            "distinct null conversion states" in item
            and "source/destination pointer/count behavior" in item
            and "positive-capacity UTF-8 mbsrtowcs resume" in item
            and "candidate-only mixed-parser rejection" in item
            and "CTYPE-only built-in UTF-8" in item
            for item in header_prerequisites
        ),
        "static-c-named-locale-multibyte must record its selected runtime boundary",
    )

    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-locale-multibyte"},
        "static-c-named-locale-multibyte must use the closed libc-locale-multibyte command",
    )

    static_root = (ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs").read_text(
        encoding="utf-8"
    )
    require(
        '#[path = "locale_multibyte.rs"]\nmod locale_multibyte;' in static_root,
        "x86 static C ABI must compose the locale_multibyte leaf",
    )
    implementation = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "locale_multibyte.rs"
    ).read_text(encoding="utf-8")
    for symbol in NAMED_LOCALE_MULTIBYTE_SYMBOLS:
        require(
            f"fn {symbol}(" in implementation,
            f"locale_multibyte leaf omits {symbol}",
        )
    for snippet in (
        "[(false, &C_NAME[..]), (true, &UTF8_NAME[..])]",
        "LC_CTYPE_UTF8_MASK",
        "category != LC_CTYPE as usize && utf8",
        "(state == LC_CTYPE_UTF8_MASK).then_some(state)",
        "MBRTOWC_INTERNAL_STATE",
        "MBRLEN_INTERNAL_STATE",
        "noninitial UTF-8 resume with positive output capacity",
    ):
        require(
            snippet in implementation,
            f"locale_multibyte leaf omits its closed {snippet} boundary",
        )

    exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    for symbol in NAMED_LOCALE_MULTIBYTE_SYMBOLS:
        require(
            symbol in exports,
            f"static C ABI export contract omits {symbol}",
        )

    header_runner = (
        ROOT / "compat" / "x86_64" / "run_locale_multibyte_header_abi.sh"
    ).read_text(encoding="utf-8")
    for snippet in ("C11/C++17", "check_cxx_c_linkage", "locale_t", "unmangled"):
        require(
            snippet in header_runner,
            f"locale/multibyte header runner omits {snippet}",
        )
    runner = (ROOT / "compat" / "x86_64" / "run_libc_locale_multibyte.sh").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "run_locale_multibyte_header_abi.sh",
        "-nostdlib -static",
        "--no-undefined",
        "R_X86_64_TPOFF",
        "__errno_location",
        "locale-object",
        "C.UTF-8",
    ):
        require(
            snippet in runner,
            f"libc-locale-multibyte runner omits {snippet}",
        )
    fixture = (ROOT / "compat" / "x86_64" / "libc_locale_multibyte_probe.c").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "CRABC_LOCALE_MULTIBYTE_FREESTANDING",
        "POSIX;C;C;C;C;C",
        "C;C;C;C;C;C",
        "C;C.UTF-8;C;C;C;C",
        "C.UTF-8;C;C;C;C;C",
        "C.UTF-8;C.UTF-8;C.UTF-8;C.UTF-8;C.UTF-8;C.UTF-8",
        "MB_CUR_MAX != 1",
        "mbstate_t split_state",
        "mbrtowc(&decoded[0], euro_lead, 1, &split_state)",
        "mbsrtowcs(decoded, &source, 1, &split_state)",
        "source != euro_tail + 2",
    ):
        require(
            snippet in fixture,
            f"locale/multibyte fixture omits closed-parser regression {snippet}",
        )
    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    for snippet in (
        "locale-multibyte-header-abi)",
        "libc-locale-multibyte)",
        "run_locale_multibyte_header_abi()",
    ):
        require(
            snippet in dispatcher,
            f"x86 dispatcher omits {snippet}",
        )


def require_locale_profile_slice(family: Mapping[str, Any]) -> None:
    """Keep the selected fixed profile distinct from broad locale completion.

    `locale.core` has a deliberately broad historical compatibility symbol
    inventory. This selected-private record owns only the global fixed-profile
    `setlocale`/`localeconv` seam, so both the evidence and its exclusions
    must remain explicit rather than silently inheriting neighboring locale,
    multibyte, or locale-object artifacts.
    """
    slices = require_verified_slices(
        family.get("verified_slice"),
        "family[libc.text-math-locale-stdio].verified_slice",
        family.get("status", ""),
        list(family.get("capabilities", [])),
    )
    matching = [entry for entry in slices if entry.get("id") == "locale.core-fixed-profile"]
    require(
        len(matching) == 1,
        "libc.text-math-locale-stdio must contain exactly one locale.core-fixed-profile slice",
    )
    selected = matching[0]
    require(
        selected.get("capabilities") == ["locale.core"],
        "locale.core-fixed-profile must select exactly locale.core",
    )
    require(
        family.get("status") == "planned",
        "locale.core-fixed-profile must not promote libc.text-math-locale-stdio",
    )

    description = selected["description"]
    assert isinstance(description, str)
    for phrase in (
        "selected-private `locale.core` fixed-profile slice",
        "only at the `setlocale`/`localeconv` seam",
        "C.UTF-8;C;C;C;C;C",
        "immutable POSIX record",
        "CHAR_MAX",
        "Candidate-only negative checks",
        "no TLS, environment lookup, allocation",
        "does not claim every broader legacy `locale.core` spelling",
        "family completion, promotion, or public x86 support",
        "general locale or legacy-encoding databases",
    ):
        require(phrase in description, f"locale.core-fixed-profile description omits {phrase}")

    owners = set(nonempty_strings(
        selected["source_owners"], "locale.core-fixed-profile.source_owners"
    ))
    for owner in (
        "SCOPE.md",
        "COMPATIBILITY-PROFILE.md",
        "compat/upstreams.toml",
        "compat/crabc-rs/coverage.toml",
        "compat/abi/musl-1.2.6/aarch64/libc.a.static.tsv",
        "compat/ratchet/aarch64-dynamic.json",
        "libc/src/c_abi.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/locale_multibyte.rs",
        "include/limits.h",
        "include/locale.h",
        "include/stddef.h",
        "include/stdint.h",
        "compat/x86_64/locale_profile_header_abi_probe.c",
        "compat/x86_64/locale_profile_header_abi_probe.cpp",
        "compat/x86_64/run_locale_profile_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_locale_profile_probe.c",
        "compat/x86_64/libc_locale_profile_start.S",
        "compat/x86_64/run_libc_locale_profile.sh",
        "compat/x86_64/aarch64_parity_inventory.py",
        "compat/x86_64/aarch64_parity_inventory.json",
        "compat/x86_64/tests/test_aarch64_parity_inventory.py",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "x86-64.md",
        "scripts/dev-x86_64.sh",
    ):
        require(owner in owners, f"locale.core-fixed-profile source owners omit {owner}")

    abi_prerequisites = "\n".join(nonempty_strings(
        selected["x86_abi_prerequisites"],
        "locale.core-fixed-profile.x86_abi_prerequisites",
    ))
    for phrase in (
        "signed 32-bit locale category",
        "96-byte/align-8",
        "src/locale/setlocale.c",
        "src/locale/locale_map.c",
        "src/locale/localeconv.c",
        "LC_CTYPE",
        "CHAR_MAX",
        "atomically locked fixed global category state",
        "no TLS, syscall, errno, allocator, locale object, locale database, environment",
        "raw write=1",
    ):
        require(phrase in abi_prerequisites, f"locale.core-fixed-profile ABI map omits {phrase}")

    header_prerequisites = "\n".join(nonempty_strings(
        selected["x86_header_prerequisites"],
        "locale.core-fixed-profile.x86_header_prerequisites",
    ))
    for phrase in (
        "strict project-first/pinned-musl C11/C++17 matrix",
        "six category values",
        "96-byte lconv offsets/types",
        "setlocale char *(*)(int, const char *)",
        "localeconv struct lconv *(*)(void)",
        "unmangled C++ references",
        "locale_t, locale objects, `_l` APIs",
        "candidate-only rejection",
        "without state mutation",
    ):
        require(phrase in header_prerequisites, f"locale.core-fixed-profile header map omits {phrase}")

    exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    for symbol in LOCALE_PROFILE_SYMBOLS:
        require(symbol in exports, f"locale.core fixed-profile export contract omits {symbol}")

    static_root = (ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs").read_text(
        encoding="utf-8"
    )
    require(
        '#[path = "locale_multibyte.rs"]\nmod locale_multibyte;' in static_root,
        "x86 static C ABI must compose the fixed locale-profile leaf",
    )
    implementation = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "locale_multibyte.rs"
    ).read_text(encoding="utf-8")
    for snippet in (
        "9fa28ece75d8a2191de7c5bb53bed224c5947417",
        "src/locale/setlocale.c",
        "src/locale/locale_map.c",
        "src/locale/localeconv.c",
        "LC_ALL_RESULT",
        "POSIX_LCONV",
        "setlocale(category, \"\")",
        "run_libc_locale_profile.sh",
    ):
        require(snippet in implementation, f"locale_multibyte fixed-profile leaf omits {snippet}")
    for symbol in LOCALE_PROFILE_SYMBOLS:
        require(
            f"fn {symbol}(" in implementation,
            f"locale_multibyte fixed-profile leaf omits {symbol}",
        )

    aarch64_source = (ROOT / "libc" / "src" / "c_abi.rs").read_text(encoding="utf-8")
    for symbol in LOCALE_PROFILE_SYMBOLS:
        require(
            f'extern "C" fn {symbol}(' in aarch64_source,
            f"AArch64 C ABI owner omits {symbol}",
        )
    aarch64_static = (
        ROOT / "compat" / "abi" / "musl-1.2.6" / "aarch64" / "libc.a.static.tsv"
    ).read_text(encoding="utf-8")
    aarch64_dynamic = (
        ROOT / "compat" / "ratchet" / "aarch64-dynamic.json"
    ).read_text(encoding="utf-8")
    for symbol in LOCALE_PROFILE_SYMBOLS:
        require(
            f"\n{symbol}\t" in aarch64_static,
            f"pinned AArch64 musl static manifest omits {symbol}",
        )
        require(
            f'"{symbol}": {{' in aarch64_dynamic,
            f"AArch64 dynamic export ratchet omits {symbol}",
        )

    header_runner = (
        ROOT / "compat" / "x86_64" / "run_locale_profile_header_abi.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "C11/C++17",
        "CXX_SYMBOLS=(setlocale localeconv)",
        "-nostdinc",
        "check_cxx_c_linkage",
        "C-linkage",
        "no locale objects, `_l` APIs, conversion, collation",
    ):
        require(snippet in header_runner, f"locale-profile header runner omits {snippet}")
    runtime_runner = (
        ROOT / "compat" / "x86_64" / "run_libc_locale_profile.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "run_locale_profile_header_abi.sh",
        "-nostdlib -static",
        "--gc-sections",
        "candidate retains TLS",
        "CRABC_LOCALE_PROFILE_FREESTANDING",
        "__ctype_get_mb_cur_max",
        "locale-object",
        "getenv",
        "setlocale-disassembly",
    ):
        require(snippet in runtime_runner, f"libc-locale-profile runner omits {snippet}")
    fixture = (
        ROOT / "compat" / "x86_64" / "libc_locale_profile_probe.c"
    ).read_text(encoding="utf-8")
    for snippet in (
        "locale-profile-fnv1a64",
        "C.UTF-8;C;C;C;C;C",
        "CHAR_MAX",
        "CRABC_LOCALE_PROFILE_FREESTANDING",
        "setlocale(LC_ALL, \"\")",
        "en_US.UTF-8",
        "C;C;C;C;C;C",
        "C;C.UTF-8;C;C;C;C",
    ):
        require(snippet in fixture, f"locale-profile fixture omits closed boundary {snippet}")

    evidence = selected["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-locale-profile"},
        "locale.core-fixed-profile must use the closed libc-locale-profile command",
    )
    scope = evidence[0].get("scope")
    require(
        isinstance(scope, str)
        and all(
            phrase in scope
            for phrase in (
                "strict C11/C++17 declaration/linkage oracle",
                "C.UTF-8;C;C;C;C;C",
                "immutable 96-byte lconv contents",
                "empty environment selection",
                "unreturned mixed forms",
                "PT_TLS/dynamic TLS",
                "conversion, locale-object, allocation, environment, gettext, numeric, time, stdio",
                "family completion, promotion, or public x86 support",
            )
        ),
        "locale.core-fixed-profile evidence omits its fixed-profile non-promotion boundary",
    )

    oracle = selected["oracle"]
    assert isinstance(oracle, list)
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "c-posix"
            and isinstance(entry.get("role"), str)
            and all(
                snippet in entry["role"]
                for snippet in (
                    "src/locale/setlocale.c",
                    "locale_map.c",
                    "localeconv.c",
                    "environment lookup",
                    "allocation paths",
                )
            )
            for entry in oracle
        ),
        "locale.core-fixed-profile must retain its pinned musl boundary oracle",
    )
    require(
        any(
            isinstance(entry, Mapping)
            and entry.get("kind") == "aarch64-contract"
            and isinstance(entry.get("source"), str)
            and "libc/src/c_abi.rs" in entry["source"]
            and "aarch64/libc.a.static.tsv" in entry["source"]
            and isinstance(entry.get("role"), str)
            and "not a behavioral fallback" in entry["role"]
            for entry in oracle
        ),
        "locale.core-fixed-profile must retain its bounded AArch64 ownership oracle",
    )

    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    for snippet in (
        "locale-profile-header-abi)",
        "libc-locale-profile)",
        "run_locale_profile_header_abi()",
        "/workspace/compat/x86_64/run_libc_locale_profile.sh",
    ):
        require(snippet in dispatcher, f"x86 dispatcher omits {snippet}")


def require_bounded_regex_artifact(family: Mapping[str, Any]) -> None:
    """Keep the bounded C matcher as evidence, not regex-family promotion."""

    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.text-math-locale-stdio].verified_artifact",
        family.get("status", ""),
    )
    matching = [
        entry for entry in artifacts
        if entry.get("id") == "static-c-bounded-regex"
    ]
    require(
        len(matching) == 1,
        "libc.text-math-locale-stdio must contain exactly one static-c-bounded-regex artifact",
    )
    require(
        family.get("status") == "planned",
        "static-c-bounded-regex must not promote libc.text-math-locale-stdio",
    )
    family_capabilities = family.get("capabilities")
    assert isinstance(family_capabilities, list)
    require(
        "pattern.regex" in family_capabilities
        and "pattern.wordexp" in family_capabilities,
        "bounded regex must remain inside the planned regex/wordexp family contract",
    )

    artifact = matching[0]
    require(
        "capabilities" not in artifact,
        "static-c-bounded-regex must not promote pattern.regex",
    )
    description = artifact["description"]
    assert isinstance(description, str)
    for phrase in (
        "still-planned `libc.text-math-locale-stdio`",
        "musl-shaped `regex_t`/`regmatch_t` ABI",
        "leftmost-longest whole-match reporting",
        "128 atoms",
        "4096 bytes",
        "private fixed 8192-byte anonymous mapping",
        "does not complete `pattern.regex`",
        "select `pattern.wordexp`",
        "family completion, promotion, or public x86 support",
    ):
        require(
            phrase in description,
            f"static-c-bounded-regex description omits {phrase}",
        )
    for unselected in (
        "groups",
        "alternation",
        "counted repetition",
        "backreferences",
        "named character classes",
        "collating/equivalence elements",
        "non-ASCII pattern bytes",
    ):
        require(
            unselected in description,
            f"static-c-bounded-regex description omits rejection of {unselected}",
        )

    owners = nonempty_strings(
        artifact["source_owners"], "static-c-bounded-regex.source_owners"
    )
    for owner in (
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/regex.rs",
        "include/bits/alltypes.h",
        "include/regex.h",
        "compat/x86_64/regex_header_abi_probe.c",
        "compat/x86_64/regex_header_abi_probe.cpp",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_regex_probe.c",
        "compat/x86_64/libc_regex_start.S",
        "compat/x86_64/run_libc_regex.sh",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "scripts/dev-x86_64.sh",
    ):
        require(owner in owners, f"static-c-bounded-regex omits {owner}")

    abi_prerequisites = nonempty_strings(
        artifact["x86_abi_prerequisites"],
        "static-c-bounded-regex.x86_abi_prerequisites",
    )
    require(
        any(
            "64-byte/align-8 regex_t" in item
            and "16-byte/align-8 regmatch_t" in item
            and "signed LP64 regoff_t" in item
            for item in abi_prerequisites
        ),
        "static-c-bounded-regex must record its public x86 layouts",
    )
    require(
        any(
            "mmap=9" in item
            and "munmap=11" in item
            and "no public malloc/calloc/realloc/free boundary" in item
            for item in abi_prerequisites
        ),
        "static-c-bounded-regex must record its private mapping lifetime",
    )

    header_prerequisites = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-bounded-regex.x86_header_prerequisites",
    )
    require(
        any(
            "C11 and C++17" in item
            and "all thirteen POSIX result values" in item
            and "unmangled C++ references" in item
            for item in header_prerequisites
        ),
        "static-c-bounded-regex must record the C/C++ header ABI boundary",
    )

    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-regex"},
        "static-c-bounded-regex must use the closed libc-regex command",
    )

    static_root = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs"
    ).read_text(encoding="utf-8")
    require(
        '#[path = "regex.rs"]\nmod regex;' in static_root,
        "x86 static C ABI must compose the bounded regex leaf",
    )
    implementation = (
        ROOT / "libc" / "src" / "c_abi" / "x86_64" / "regex.rs"
    ).read_text(encoding="utf-8")
    for symbol in BOUNDED_REGEX_SYMBOLS:
        require(
            f"fn {symbol}(" in implementation,
            f"bounded regex leaf omits {symbol}",
        )
    for snippet in (
        "MAX_TOKENS: usize = 128",
        "MAX_PATTERN_BYTES: usize = 4_096",
        "MAX_INPUT_BYTES: usize = 4_096",
        "COMPILED_MAPPING_BYTES: usize = 8_192",
        "raw_syscall::SYS_MMAP",
        "raw_syscall::SYS_MUNMAP",
    ):
        require(
            snippet in implementation,
            f"bounded regex leaf omits {snippet}",
        )

    exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    for symbol in BOUNDED_REGEX_SYMBOLS:
        require(symbol in exports, f"static C ABI export contract omits {symbol}")
    for unselected in ("wordexp", "wordfree", "glob", "globfree", "fnmatch"):
        require(
            unselected not in exports,
            f"bounded regex artifact promoted unselected {unselected}",
        )

    fixture = (
        ROOT / "compat" / "x86_64" / "libc_regex_probe.c"
    ).read_text(encoding="utf-8")
    for snippet in (
        "CRABC_REGEX_FREESTANDING",
        "a.*a",
        "REG_NEWLINE",
        "REG_NOSUB",
        "REG_ESPACE",
        "[[:digit:]]",
    ):
        require(snippet in fixture, f"bounded regex fixture omits {snippet}")
    runner = (
        ROOT / "compat" / "x86_64" / "run_libc_regex.sh"
    ).read_text(encoding="utf-8")
    for snippet in (
        "-nostdlib -static",
        "--no-undefined",
        "static_c_abi_exports.txt",
        "wordexp wordfree malloc calloc realloc free",
        "raw_syscall::SYS_MMAP",
        "raw_syscall::SYS_MUNMAP",
    ):
        require(snippet in runner, f"bounded regex runner omits {snippet}")
    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    require("libc-regex)" in dispatcher, "x86 dispatcher omits libc-regex")


def require_locale_wide_iconv_artifact(family: Mapping[str, Any]) -> None:
    """Keep the fixed UTF/ASCII iconv composition below broad text parity.

    This is intentionally a descriptor-token and pointer-progress proof, not
    a general encoding registry or a way to promote the named locale artifact
    into wide-text, iconv, or locale-family completion.
    """
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.text-math-locale-stdio].verified_artifact",
        family.get("status", ""),
    )
    require(
        len(artifacts) == 38,
        "libc.text-math-locale-stdio must retain exactly thirty-eight private verified artifacts",
    )
    matching = [
        entry for entry in artifacts if entry.get("id") == "static-c-locale-wide-iconv"
    ]
    require(
        len(matching) == 1,
        "libc.text-math-locale-stdio must contain exactly one static-c-locale-wide-iconv artifact",
    )
    artifact = matching[0]
    description = artifact["description"]
    assert isinstance(description, str)
    for symbol in LOCALE_WIDE_ICONV_SYMBOLS:
        require(
            f"`{symbol}`" in description,
            f"static-c-locale-wide-iconv description omits {symbol}",
        )
    for phrase in (
        "selected-static C composition",
        "C.UTF-8",
        "mbstate_t",
        "ASCII, UTF-8, UTF-16LE/BE, UTF-32LE/BE",
        "WCHAR_T",
        "allocation-free token",
        "exact fuzzy name normalization boundary",
        "fixed-endian UTF-16 and UTF-32 byte order",
        "ASCII `'*'` substitution",
        "EILSEQ",
        "E2BIG",
        "UCS-2",
        "legacy codepages",
        "wide streams/stdio",
        "family completion",
        "promotion",
        "public x86 support",
    ):
        require(
            phrase in description,
            f"static-c-locale-wide-iconv description omits {phrase}",
        )

    owners = nonempty_strings(
        artifact["source_owners"], "static-c-locale-wide-iconv.source_owners"
    )
    for owner in (
        "libc/src/c_abi.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/locale_multibyte.rs",
        "libc/src/c_abi/x86_64/iconv.rs",
        "include/iconv.h",
        "compat/x86_64/iconv_header_abi_probe.c",
        "compat/x86_64/iconv_header_abi_probe.cpp",
        "compat/x86_64/run_iconv_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_locale_wide_iconv_probe.c",
        "compat/x86_64/libc_locale_wide_iconv_start.S",
        "compat/x86_64/run_libc_locale_wide_iconv.sh",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "x86-64.md",
        "scripts/dev-x86_64.sh",
    ):
        require(
            owner in owners,
            f"static-c-locale-wide-iconv omits {owner}",
        )

    abi_prerequisites = nonempty_strings(
        artifact["x86_abi_prerequisites"],
        "static-c-locale-wide-iconv.x86_abi_prerequisites",
    )
    require(
        any("System V AMD64" in item and "iconv_t" in item and "WCHAR_T" in item
            for item in abi_prerequisites),
        "static-c-locale-wide-iconv must record its x86 pointer/WCHAR_T ABI",
    )
    require(
        any(
            "src/locale/iconv.c" in item
            and "iconv_close.c" in item
            and "stateful descriptor allocation" in item
            for item in abi_prerequisites
        ),
        "static-c-locale-wide-iconv must record its pinned-musl source boundary",
    )
    require(
        any("initial-exec errno TLS" in item and "no allocator" in item
            for item in abi_prerequisites),
        "static-c-locale-wide-iconv must record its allocation/TLS boundary",
    )

    header_prerequisites = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-locale-wide-iconv.x86_header_prerequisites",
    )
    require(
        any("C11/C++17" in item and "unmangled C++ C linkage" in item
            for item in header_prerequisites),
        "static-c-locale-wide-iconv must record its C/C++ header ABI boundary",
    )

    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-locale-wide-iconv"},
        "static-c-locale-wide-iconv must use the closed libc-locale-wide-iconv command",
    )
    oracles = artifact["oracle"]
    assert isinstance(oracles, list)
    require(
        any(
            entry.get("kind") == "project-contract"
            and "AArch64" in str(entry.get("source"))
            and "libc/src/c_abi.rs" in str(entry.get("source"))
            and "does not inherit" in str(entry.get("role"))
            for entry in oracles
        ),
        "static-c-locale-wide-iconv must record its bounded AArch64 project oracle",
    )

    static_root = (ROOT / "libc" / "src" / "c_abi" / "x86_64" / "static_c_abi.rs").read_text(
        encoding="utf-8"
    )
    require(
        '#[path = "iconv.rs"]\nmod iconv;' in static_root,
        "x86 static C ABI must compose the iconv leaf",
    )
    implementation = (ROOT / "libc" / "src" / "c_abi" / "x86_64" / "iconv.rs").read_text(
        encoding="utf-8"
    )
    for symbol in LOCALE_WIDE_ICONV_SYMBOLS:
        require(
            f"fn {symbol}(" in implementation,
            f"x86 iconv leaf omits {symbol}",
        )
    for snippet in (
        "ENC_UTF8",
        "ENC_UTF16LE",
        "ENC_UTF32BE",
        "ENC_WCHAR_T",
        "ENC_ASCII",
        "DecodeError::Incomplete",
        "DecodeError::Invalid",
        "E2BIG",
        "EILSEQ",
        "make_descriptor",
        "publish_progress",
        "wrapping_sub(b'a') > 26",
        "wrapping_sub(b'0') > 10",
    ):
        require(
            snippet in implementation,
            f"x86 iconv leaf omits its closed {snippet} boundary",
        )
    require(
        'name_matches(name, b"ucs2le")' not in implementation
        and 'name_matches(name, b"ucs2be")' not in implementation,
        "x86 iconv leaf must not silently select UCS-2 aliases",
    )

    exports = static_c_abi_export_names(
        ROOT / "compat" / "x86_64" / "static_c_abi_exports.txt"
    )
    for symbol in LOCALE_WIDE_ICONV_SYMBOLS:
        require(symbol in exports, f"static C ABI export contract omits {symbol}")

    header = (ROOT / "include" / "iconv.h").read_text(encoding="utf-8")
    for snippet in ("extern \"C\"", "typedef void *iconv_t", "iconv_open", "iconv_close"):
        require(snippet in header, f"project iconv.h omits {snippet}")
    header_runner = (ROOT / "compat" / "x86_64" / "run_iconv_header_abi.sh").read_text(
        encoding="utf-8"
    )
    for snippet in ("C11/C++17", "unmangled", "nm --undefined-only", "iconv_open"):
        require(snippet in header_runner, f"iconv header runner omits {snippet}")
    runner = (ROOT / "compat" / "x86_64" / "run_libc_locale_wide_iconv.sh").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "run_locale_multibyte_header_abi.sh",
        "run_iconv_header_abi.sh",
        "-nostdlib -static",
        "--no-undefined",
        "R_X86_64_TPOFF",
        "iconv_open",
        "malloc",
    ):
        require(snippet in runner, f"libc-locale-wide-iconv runner omits {snippet}")
    fixture = (ROOT / "compat" / "x86_64" / "libc_locale_wide_iconv_probe.c").read_text(
        encoding="utf-8"
    )
    for snippet in (
        "CRABC_LOCALE_WIDE_ICONV_FREESTANDING",
        "UTF-16LE",
        "UTF-16BE",
        "Ut_F-32BE",
        "WCHAR_T",
        "ASCII",
        "EILSEQ",
        "E2BIG",
        "UTF-8-",
        "UTF:8",
        "invalid_utf16le",
        "invalid_utf32le",
        "UCS-2LE",
    ):
        require(snippet in fixture, f"locale/wide/iconv fixture omits {snippet}")
    dispatcher = (ROOT / "scripts" / "dev-x86_64.sh").read_text(encoding="utf-8")
    for snippet in (
        "iconv-header-abi)",
        "libc-locale-wide-iconv)",
        "run_iconv_header_abi()",
    ):
        require(snippet in dispatcher, f"x86 dispatcher omits {snippet}")


def require_wide_character_artifact(family: Mapping[str, Any]) -> None:
    """Keep the Unicode wide core exact, allocation-free, and non-promoting."""
    artifacts = require_verified_artifacts(
        family.get("verified_artifact"),
        "family[libc.text-math-locale-stdio].verified_artifact",
        family.get("status", ""),
    )
    matching = [
        entry for entry in artifacts if entry.get("id") == "static-c-wide-character-core"
    ]
    require(
        len(matching) == 1,
        "libc.text-math-locale-stdio must contain exactly one static-c-wide-character-core artifact",
    )
    artifact = matching[0]
    description = artifact["description"]
    assert isinstance(description, str)
    for symbol in WIDE_CHARACTER_SYMBOLS:
        require(
            f"`{symbol}`" in description or symbol.startswith(("wcs", "wmem", "isw")),
            f"static-c-wide-character-core description omits {symbol}",
        )
    for phrase in (
        "allocation-free wide-character core",
        "C/POSIX/C.UTF-8",
        "compressed Unicode",
        "U+0000 through U+110000",
        "wcsdup",
        "locale-object/`*_l`",
        "legacy-encoding database",
        "wide stdio/streams",
        "family completion",
        "promotion",
        "public x86 support",
    ):
        require(
            phrase in description,
            f"static-c-wide-character-core description omits {phrase}",
        )

    owners = nonempty_strings(
        artifact["source_owners"], "static-c-wide-character-core.source_owners"
    )
    for owner in (
        "libc/src/c_abi.rs",
        "libc/src/c_abi/x86_64/static_c_abi.rs",
        "libc/src/c_abi/x86_64/wide_character.rs",
        "libc/src/c_abi/x86_64/wide_character_tables.rs",
        "include/bits/alltypes.h",
        "include/wchar.h",
        "include/wctype.h",
        "compat/x86_64/wide_character_header_abi_probe.c",
        "compat/x86_64/wide_character_header_abi_probe.cpp",
        "compat/x86_64/run_wide_character_header_abi.sh",
        "compat/x86_64/static_c_abi_exports.txt",
        "compat/x86_64/libc_wide_character_probe.c",
        "compat/x86_64/libc_wide_character_start.S",
        "compat/x86_64/run_libc_wide_character.sh",
        "compat/x86_64/tests/test_runner.py",
        "compat/x86_64/tests/test_parity_ledger.py",
        "compat/x86_64/validate_parity_ledger.py",
        "compat/x86_64/README.md",
        "STATUS.md",
        "x86-64.md",
        "scripts/dev-x86_64.sh",
    ):
        require(owner in owners, f"static-c-wide-character-core omits {owner}")

    abi_prerequisites = nonempty_strings(
        artifact["x86_abi_prerequisites"],
        "static-c-wide-character-core.x86_abi_prerequisites",
    )
    require(
        any("signed 32-bit" in item and "wctype_t" in item and "wctrans_t" in item
            for item in abi_prerequisites),
        "static-c-wide-character-core must record its x86 wide ABI",
    )
    require(
        any("alpha.h" in item and "casemap.h" in item and "MIT license" in item
            for item in abi_prerequisites),
        "static-c-wide-character-core must record the pinned-musl table mapping",
    )
    require(
        any("no errno" in item and "no TLS" in item and "no locale object" in item
            for item in abi_prerequisites),
        "static-c-wide-character-core must record its allocation/state boundary",
    )
    header_prerequisites = nonempty_strings(
        artifact["x86_header_prerequisites"],
        "static-c-wide-character-core.x86_header_prerequisites",
    )
    require(
        any("C11/C++17" in item and "46 selected declarations" in item
            for item in header_prerequisites),
        "static-c-wide-character-core must record its exact header ABI",
    )
    evidence = artifact["native_evidence"]
    assert isinstance(evidence, list)
    require(
        {entry["command"] for entry in evidence}
        == {"./scripts/dev-x86_64.sh libc-wide-character"},
        "static-c-wide-character-core must use the closed libc-wide-character command",
    )
    oracles = artifact["oracle"]
    assert isinstance(oracles, list)
    require(
        any(
            entry.get("kind") == "project-contract"
            and "AArch64" in str(entry.get("source"))
            and "does not inherit" in str(entry.get("role"))
            for entry in oracles
        ),
        "static-c-wide-character-core must record its bounded AArch64 oracle",
    )

